#!/usr/bin/env bash
# Runs in the work dir after the last turn; prints one JSON object of named
# booleans. Generated by bench/search_fixtures.py: the expected answer was
# computed from the tracked files of the fixture, not written by hand.
exec "${BENCH_PYTHON:-python3}" - <<'PY'
import json, os, re, subprocess, sys
from pathlib import Path

EXPECTED = json.loads('{"old_in_code_and_docs": 32}')
def read(p):
    return Path(p).read_text() if Path(p).exists() else ""

remaining = 0
for p in subprocess.run(["git", "ls-files"], capture_output=True, text=True).stdout.split():
    if p != "CHANGELOG.md" and p.endswith((".py", ".md")):
        remaining += len(re.findall(r"\bfetch_user_record\b", read(p)))
store = read("pkg/users/store.py")
cache = read("pkg/users/cache.py")
tests = subprocess.run([sys.executable, "-m", "unittest", "discover", "-s", "tests", "-t", "."], capture_output=True, text=True)
print(json.dumps({
    "renamed": "def load_user_record(" in store,
    "no_old_name_left": remaining == 0,
    "plural_untouched": "def fetch_user_records(" in store,
    "prefetch_untouched": "def prefetch_user_record(" in cache,
    "changelog_untouched": "fetch_user_record for single lookups" in read("CHANGELOG.md"),
    "tests_pass": tests.returncode == 0,
}))
PY
